      ro: ["Comisionat: 1881", "Înălțimea turnului: 26 de metri", "Număr de trepte: 132", "Raza de acțiune a luminii: 21,8 mile marine", "Material: Piatră", "Locație: Parcul Național Cabo Polonio"],
      en: ["Commissioned: 1881", "Tower Height: 26 meters", "Number of steps: 132", "Light Range: 21.8 nautical miles", "Material: Stone", "Location: Cabo Polonio National Park"],
      es: ["El Faro de Cabo Polonio ofrece una visión profunda de la cultura y tradición regional.", "El lugar se caracteriza por su diversidad arquitectónica e importancia histórica.", "Los viajeros encontrarán en los alrededores del Faro de Cabo Polonio diversas oportunidades para actividades de ocio."],
      pt: ["O Faro de Cabo Polonio oferece uma visão profunda da cultura e tradição regional.", "O local caracteriza-se pela sua diversidade arquitetónica e importância histórica.", "Os viajantes encontrarão nos arredores do Faro de Cabo Polonio diversas oportunidades para atividades de lazer."],
      fr: ["Le Faro de Cabo Polonio offre un aperçu profond de la culture et de la tradition régionales.", "Le lieu se caractérise par sa diversité architecturale et son importance historique.", "Les voyageurs trouveront dans les environs du Faro de Cabo Polonio de nombreuses opportunités d'activités de loisirs."],
