    description: { de: "Der Hauptsitz des Außenministeriums Uruguays, ein beeindruckendes historisches Gebäude in Montevideo.", hu: "Az uruguayi Külügyminisztérium központja, egy lenyűgöző történelmi épület Montevideóban.", ro: "Sediul Ministerului Afacerilor Externe din Uruguay, o clădire istorică impresionantă din Montevideo.", en: "The headquarters of the Ministry of Foreign Affairs of Uruguay, an impressive historic building in Montevideo." , es: "La sede principal del Ministerio de Relaciones Exteriores de Uruguay, un impresionante edificio histórico en Montevideo.", pt: "A sede principal do Ministério das Relações Exteriores do Uruguai, um impressionante edifício histórico em Montevideu.", fr: "Le siège principal du ministère des Affaires étrangères de l'Uruguay, un impressionnant bâtiment historique à Montevideo."},
    
    facts: {
      de: ["1885 erbaut", "Residenz des Präsidenten Máximo Santos", "Beinhaltet luxuriöse Materialien", "Staatseigentum seit 1890"],
      hu: ["1885-ben épült", "Máximo Santos elnök rezidenciája volt", "Fényűző anyagokat tartalmaz", "1890 óta állami tulajdon"],
      ro: ["Construit în 1885", "A fost reședința președintelui Máximo Santos", "Include materiale luxoase", "Proprietate de stat din 1890"],
      en: ["Built in 1885", "Was residence of President Máximo Santos", "Incorporates luxurious materials", "State property since 1890"],
      es: ["Construido en 1885", "Residencia del presidente Máximo Santos", "Incluye materiales lujosos", "Propiedad del estado desde 1890"],
      pt: ["Construído em 1885", "Residência do presidente Máximo Santos", "Inclui materiais luxuosos", "Propriedade do estado desde 1890"],
      fr: ["Construit en 1885", "Résidence du président Máximo Santos", "Comprend des matériaux luxueux", "Propriété de l'État depuis 1890"],
    },
    descriptionAdvanced: {
      de: "Der Palacio Santos, offiziell als Estévez-Palast bekannt, ist ein emblematisches Gebäude in Montevideo und der zeremonielle Sitz des uruguayischen Außenministeriums. Der Bau wurde 1885 als Privatresidenz für Präsident Máximo Santos in Auftrag gegeben und vom Architekten Juan Alberto Capurro entworfen. Der Palast ist ein herausragendes Beispiel für den eklektischen Historismus, der für das späte 19. Jahrhundert typisch ist, und kombiniert Elemente des italienischen Renaissance-Revivals und der französischen Beaux-Arts-Architektur. Seine Fassade zeichnet sich durch aufwendige Verzierungen aus, während die Innenräume reich mit Marmor, Stuck, Buntglas und edlen Hölzern dekoriert sind. Besonders bemerkenswert ist der „Saal der Spiegel“, der vom Spiegelsaal im Schloss Versailles inspiriert ist. Nachdem Santos seine Präsidentschaft beendet hatte, wurde das Gebäude vom Staat erworben und seit 1908 beherbergt es das Außenministerium. Es ist nicht nur ein Arbeitsplatz für Diplomaten, sondern auch ein Museum, das seine reiche Geschichte und Kunstsammlungen zeigt.",
      hu: "A Santos-palota, hivatalos nevén Estévez-palota, Montevideo egyik emblematikus épülete, és az Uruguayi Külügyminisztérium ceremoniális székhelye. Az épületet 1885-ben kezdték építeni Máximo Santos elnök magánrezidenciájaként, Juan Alberto Capurro építész tervei alapján. A palota a 19. század végére jellemző eklektikus historizmus kiemelkedő példája, amely ötvözi az olasz reneszánsz és a francia Beaux-Arts építészet elemeit. Homlokzatát gazdag díszítés jellemzi, míg belső tereit márvánnyal, stukkóval, ólomüveg ablakokkal és nemes fákkal díszítették. Különösen figyelemre méltó a „Tükörterem”, amelyet a versailles-i kastély Tükörgalériája ihletett. Miután Santos befejezte elnökségét, az épületet az állam megvásárolta, és 1908 óta a Külügyminisztériumnak ad otthont. Nemcsak diplomaták munkahelye, hanem múzeum is, amely bemutatja gazdag történelmét és művészeti gyűjteményeit.",
      ro: "Palatul Santos, cunoscut oficial ca Palatul Estévez, este o clădire emblematică din Montevideo și sediul ceremonial al Ministerului Afacerilor Externe al Uruguayului. Construcția sa a fost comandată în 1885 ca reședință privată pentru președintele Máximo Santos și a fost proiectată de arhitectul Juan Alberto Capurro. Palatul este un exemplu remarcabil de istoricism eclectic, tipic pentru sfârșitul secolului al XIX-lea, combinând elemente ale renașterii italiene și ale arhitecturii Beaux-Arts franceze. Fațada sa se distinge prin ornamentația sa elaborată, în timp ce interioarele sunt bogat decorate cu marmură, stucaturi, vitralii și lemn nobil. De o notabilitate deosebită este „Sala Oglinzilor”, inspirată de Galeria Oglinzilor de la Palatul Versailles. După ce Santos și-a încheiat președinția, clădirea a fost achiziționată de stat și, din 1908, găzduiește Ministerul Afacerilor Externe. Nu este doar un loc de muncă pentru diplomați, ci și un muzeu care prezintă istoria sa bogată și colecțiile de artă.",
      en: "The Santos Palace, officially known as the Estévez Palace, is an emblematic building in Montevideo and the ceremonial headquarters of the Ministry of Foreign Affairs of Uruguay. Its construction was commissioned in 1885 as the private residence for President Máximo Santos and was designed by architect Juan Alberto Capurro. The palace is an outstanding example of the eclectic historicism typical of the late 19th century, combining elements of Italian Renaissance Revival and French Beaux-Arts architecture. Its facade is distinguished by its elaborate ornamentation, while its interiors are richly decorated with marble, stucco, stained glass, and fine woods. Of particular note is the 'Hall of Mirrors', inspired by the Hall of Mirrors at the Palace of Versailles. After Santos finished his presidency, the building was acquired by the state, and since 1908, it has housed the Ministry of Foreign Affairs. It is not only a workplace for diplomats but also a museum showcasing its rich history and art collections.",
      es: "El Palacio Santos es uno de los sitios más importantes de Uruguay, impresionando a los visitantes con su encanto único y su rica historia. Este lugar desempeña un papel central en la vida cultural y económica de la región y ofrece a los viajeros numerosas atracciones y experiencias. Gracias a su ubicación estratégica y su vibrante comunidad, es un destino clave para quienes desean conocer el Uruguay auténtico. La arquitectura, la artesanía local y las especialidades culinarias definen la imagen de la zona y hacen que la estancia sea un recuerdo duradero. Los visitantes aprecian especialmente la hospitalidad de los lugareños y la atmósfera relajada que se siente en todas partes.",
      pt: "O Palacio Santos é um dos locais mais importantes do Uruguai, impressionando os visitantes com o seu charme único e rica história. Este lugar desempenha um papel central na vida cultural e económica da região e oferece aos viajantes inúmeras atrações e experiências. Graças à sua localização estratégica e comunidade vibrante, é um destino fundamental para quem deseja conhecer o Uruguai autêntico. A arquitetura, o artesanato local e as especialidades culinárias moldam a imagem da zona e tornam a estadia uma memória duradoura. Os visitantes apreciam especialmente a hospitalidade dos habitantes locais e a atmosfera relaxada que se sente em todo o lado.",
      fr: "Le Palacio Santos est l'un des sites les plus importants de l'Uruguay, impressionnant les visiteurs par son charme unique et sa riche histoire. Ce lieu joue un rôle central dans la vie culturelle et économique de la région et offre aux voyageurs de nombreuses attractions et expériences. Grâce à son emplacement stratégique et à sa communauté dynamique, c'est une destination clé pour ceux qui souhaitent découvrir l'Uruguay authentique. L'architecture, l'artisanat local et les spécialités culinaires marquent l'image de la région et font du séjour un souvenir impérissable. Les visiteurs apprécient particulièrement l'hospitalité des habitants et l'atmosphère détendue que l'on ressent partout.",
    },
