      ro: ["Proiectat de arhitectul uruguayan Juan Alberto Capurro.", "Construcția a început în 1885 pentru președintele Máximo Santos.", "Din 1908, este sediul Ministerului Afacerilor Externe.", "Stilul este istoricism eclectic.", "„Sala Oglinzilor” este o replică a sălii de la Versailles.", "A fost declarată Monument Istoric Național în 1975."],
      en: ["Designed by Uruguayan architect Juan Alberto Capurro.", "Construction began in 1885 for President Máximo Santos.", "Since 1908, it has been the headquarters of the Ministry of Foreign Affairs.", "The style is Eclectic Historicism.", "The 'Hall of Mirrors' is a replica of the one in Versailles.", "It was declared a National Historical Monument in 1975."],
