      pt: ["O Palacio Santos oferece uma visão profunda da cultura e tradição regional.", "O local caracteriza-se pela sua diversidade arquitetónica e importância histórica.", "Os viajantes encontrarão nos arredores do Palacio Santos diversas oportunidades para atividades de lazer."],
      fr: ["Le Palacio Santos offre un aperçu profond de la culture et de la tradition régionales.", "Le lieu se caractérise par sa diversité architecturale et son importance historique.", "Les voyageurs trouveront dans les environs du Palacio Santos de nombreuses opportunités d'activités de loisirs."],
